/// Fills the editor colors from the scheme; unmapped fields keep `e`'s value.
fn editor(mut e: EditorColors) -> EditorColors {
    e.background = px(0x000000FF); // TEXT.bg
    e.text = px(0xEBEBEBFF); // TEXT.fg
    e.caret = px(0xFFFFFFFF); // CARET_COLOR
    e.caret_row = px(0x000066FF); // CARET_ROW_COLOR
    e.line_number = px(0x999999FF); // LINE_NUMBERS_COLOR
    e.line_number_caret = px(0xFFFFFFFF); // LINE_NUMBER_ON_CARET_ROW_COLOR
    e.selection = px(0x006280FF); // SELECTION_BACKGROUND
    e.background_panel = px(0x281A33FF); // DOCUMENTATION_COLOR
    e.search_result = px(0x001133FF); // TEXT_SEARCH_RESULT_ATTRIBUTES.bg
    e.rename_occurrence = px(0x003B0AFF); // IDENTIFIER_UNDER_CARET_ATTRIBUTES.bg
    e.indent_guide = px(0x666666FF); // INDENT_GUIDE
    e.error_effect = px(0xFF0D25FF); // ERRORS_ATTRIBUTES.effect
    e.warning_effect = px(0xFFB300FF); // WARNING_ATTRIBUTES.stripe
    e.weak_warning_effect = px(0xB39500FF); // INFO_ATTRIBUTES.effect
    e.breakpoint_line = px(0x4D0E00FF); // BREAKPOINT_ATTRIBUTES.bg
    e.execution_line = px(0x002673FF); // EXECUTIONPOINT_ATTRIBUTES.bg
    e.inline_value = px(0xCCCCCCFF); // DEBUGGER_INLINED_VALUES.fg
    e.error_stripe = px(0xFF0D25FF); // ERRORS_ATTRIBUTES.stripe
    e.warning_stripe = px(0xFFB300FF); // WARNING_ATTRIBUTES.stripe
    e.string = px(0x54B33EFF); // DEFAULT_STRING.fg
    e.number = px(0x33CCFFFF); // DEFAULT_NUMBER.fg
    e.keyword = px(0xED864AFF); // DEFAULT_KEYWORD.fg
    e.constant = px(0xED94FFFF); // DEFAULT_CONSTANT.fg
    e.type_name = px(0x37CCCCFF); // TYPE_PARAMETER_NAME_ATTRIBUTES.fg
    e.annotation = px(0xA9B837FF); // DEFAULT_METADATA.fg
    e.property = px(0xED94FFFF); // DEFAULT_INSTANCE_FIELD.fg
    e.punctuation = px(0xED864AFF); // DEFAULT_COMMA.fg
    e.comment = px(0x7EC3E6FF); // DEFAULT_LINE_COMMENT.fg
    e.tag = px(0xE8BF6AFF); // XML_TAG_NAME.fg
    e.attribute = px(0x0000FFFF); // XML_ATTRIBUTE_NAME.fg
    e.variable = px(0xFFCF40FF); // DEFAULT_FUNCTION_DECLARATION.fg
    e.invalid = px(0xFA3232FF); // WRONG_REFERENCES_ATTRIBUTES.fg
    // Kept at the measured value: matched_brace, search_result_current.
    e
}
